import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.BlfGB29P.js";const r="/assets/ui-minimalist-option.BHhOBuwZ.png",g=JSON.parse('{"title":"FAQ","description":"Your FAQ for UI eXtension answered here.","frontmatter":{"description":"Your FAQ for UI eXtension answered here.","hide":["toc","navigation"]},"headers":[],"relativePath":"en/projects/uix/faq.md","filePath":"en/projects/uix/faq.md","lastUpdated":1792851046000}'),s={name:"en/projects/uix/faq.md"};function i(d,e,l,c,u,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<blockquote><p>Adapted from the canonical English UIX documentation by <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Source: <code>dev</code> / <strong>9.0.0-beta.2</strong>, revision <a href="https://github.com/Lint-Free-Technology/uix/commit/26e54e6d4973231a393933e6479ed1b03cc86cd3" target="_blank" rel="noreferrer">26e54e6</a>, reviewed 22 October 2026. This source mirror may describe preview behavior beyond stable 8.4.0. Markup adapted for this site; the <a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">original documentation</a> remains authoritative.</p></blockquote><h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="how-do-i-best-migrate-from-card-mod" tabindex="-1">How do I best migrate from Card-mod? <a class="header-anchor" href="#how-do-i-best-migrate-from-card-mod" aria-label="Permalink to &quot;How do I best migrate from Card-mod?&quot;">​</a></h2><ul><li>Uninstall card-mod.</li><li>If you use extra_module_url for card-mod resource, remove and restart Home Assistant.</li><li>Proceed to follow the <a href="./quick-start">UI eXtension quick start guide</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">Add UI eXtension as a Service</p><p>UI eXtension is an integration and needs to be added as a Service once you have downloaded by HACS. Make sure you don&#39;t miss the <strong>Add UI eXtension service</strong> step. This is something you may miss if you are not accustomed to adding integrations like UIX as a Service.</p></div><details class="details custom-block"><summary>UI Lovelace Minimalist may load card-mod resource</summary><p>If you have UI Lovelace Minimalist installed it may load card-mod resource. Due to load order of integrations, UI eXtension cannot check for this conflict. To continue to use UI Lovelace Minimalist with UI eXtension you need to turn off UI Lovelace Minimalist config option <code>Include custom card resources it&#39;s depending on</code> and load any required custom cards through HACS or manually.</p><p><img src="'+r+'" alt="UI Minimalist custom card option"></p></details><h2 id="is-ui-extension-a-drop-in-replacement-for-card-mod" tabindex="-1">Is UI eXtension a drop in replacement for Card-mod? <a class="header-anchor" href="#is-ui-extension-a-drop-in-replacement-for-card-mod" aria-label="Permalink to &quot;Is UI eXtension a drop in replacement for Card-mod?&quot;">​</a></h2><p>Yes, UI eXtension is a drop in replacement for Card-mod versions up to 4.2.1. All Card-mod card and themes configurations are supported. While you are encouraged to update to use <code>uix:</code> in your cards and <code>uix-&lt;thing&gt;(-yaml)</code> for your themes, it is not required.</p><h2 id="is-ui-extension-just-card-mod-with-different-documentation" tabindex="-1">Is UI eXtension just Card-mod with different documentation? <a class="header-anchor" href="#is-ui-extension-just-card-mod-with-different-documentation" aria-label="Permalink to &quot;Is UI eXtension just Card-mod with different documentation?&quot;">​</a></h2><p>No, UI eXtension code has been updated so that UIX is primary domain and config key. Card-mod keys are supported but overridden by <code>uix:</code>.</p><details class="details custom-block"><summary>UI eXtension differences from Card-mod</summary><ul><li>Config key for cards is <code>uix:</code>.</li><li>Theme key is <code>uix-theme:</code>.</li><li>Theme <code>thing</code> keys are <code>uix-&lt;thing&gt;(-yaml):</code>.</li><li>HTML node for UI eXtension is <code>&lt;uix-node&gt;</code> and properties of the node all refer to <code>uix</code>.</li><li>You can use <code>{# uix.debug #}</code> to debug templates.</li><li>All debug console messages will start with <code>UIX</code>.</li></ul></details><h2 id="is-there-a-list-of-differences-between-card-mod-and-ui-extension" tabindex="-1">Is there a list of differences between Card-mod and UI eXtension? <a class="header-anchor" href="#is-there-a-list-of-differences-between-card-mod-and-ui-extension" aria-label="Permalink to &quot;Is there a list of differences between Card-mod and UI eXtension?&quot;">​</a></h2><p>Yes, see the table below.</p><table tabindex="0"><thead><tr><th>Feature</th><th style="text-align:center;">Card-mod</th><th style="text-align:center;">UIX</th></tr></thead><tbody><tr><td>Correctly loads <code>...-yaml</code> theme variables</td><td style="text-align:center;">❌<br>Since 2026.8.0</td><td style="text-align:center;">Yes</td></tr><tr><td>Correctly handles <code>...-more-info(-yaml)</code> theme variable</td><td style="text-align:center;">❌<br>Since 2026.3.0</td><td style="text-align:center;">Yes</td></tr><tr><td>Correctly patches adaptive dialogs for <code>...-dialog(-yaml)</code> theme variable</td><td style="text-align:center;">❌<br>Since 2026.3.0</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/concepts/dom#dom-inspection-helpers">DOM inspection helpers</a></td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/concepts/dom#hostelement-path-selection">Host/element path selection</a></td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/concepts/dom#express-search-selector">Express search selector</a></td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/forge/">Forge</a> (custom lovelace element)</td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/forge/foundries">Forge - Foundries</a> (reusable forges)</td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/using/templates#macros">Forge - Macros</a> (reusable jinja templates)</td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/forge/sparks/">Forge - Sparks</a> (self-contained behaviours that augment forged elements)</td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/broker/">Broker</a> (create declarative frontend event interactions)</td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/extras/frontend-states-throttling">Frontend state throttling</a> (optional)</td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/extras/dialog-styling-delay">Dialog Styling delay</a> (optional)</td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/using/view-backgrounds">Dashboard view backgrounds</a></td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/using/section-backgrounds">Section backgrounds</a></td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/using/view-backgrounds">View backgrounds</a></td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/using/icons#specifying-for-an-entity-override">Icon styling - entity override</a></td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/using/images">Styling entity images</a></td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/using/custom-panels">Styling custom panels</a> (including those loaded as iFrames)</td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td><a href="/en/projects/uix/using/apps">Styling app and ingress panels</a> (including those loaded as iFrames)</td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td>Reload/Clear cache popup</td><td style="text-align:center;">No</td><td style="text-align:center;">Yes</td></tr><tr><td>Expansive documentation including visual examples</td><td style="text-align:center;">Limited</td><td style="text-align:center;">Yes</td></tr><tr><td>Mod-Card</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td></tr><tr><td>CSS styling in themes</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td></tr><tr><td>Reload/Clear cache service/action</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td></tr><tr><td>Provides variables (e.g current user)</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td></tr><tr><td>CSS styling</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td></tr><tr><td>Resource url</td><td style="text-align:center;">Yes</td><td style="text-align:center;">N/A</td></tr></tbody></table><h2 id="does-ui-extension-have-resource-url-issues" tabindex="-1">Does UI eXtension have resource URL issues? <a class="header-anchor" href="#does-ui-extension-have-resource-url-issues" aria-label="Permalink to &quot;Does UI eXtension have resource URL issues?&quot;">​</a></h2><p>No, being an integration, UI eXtension manages its resource URLs directly. You don&#39;t need to do anything to have UI eXtension run at peak performance. UI eXtension dynamically adds its Frontend resource, <code>uix.js</code>, as an extra module, as well as adding a Dashboard resource in case you use CAST. UI eXtension will add its version to these resources automatically each time the integration loads.</p><h2 id="does-ui-extension-need-manual-cache-clear-after-upgrade-for-browsers-and-device-companion-apps" tabindex="-1">Does UI eXtension need manual cache clear after upgrade for Browsers and device Companion Apps? <a class="header-anchor" href="#does-ui-extension-need-manual-cache-clear-after-upgrade-for-browsers-and-device-companion-apps" aria-label="Permalink to &quot;Does UI eXtension need manual cache clear after upgrade for Browsers and device Companion Apps?&quot;">​</a></h2><p>UI eXtension will show a toast message when it detects that a reload is needed to clear caches, with a convenient <code>Reload Now</code> button and auto reload after 60s.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>While the Auto reload code is in 8.1.0, auto Reload will be available when you next update. When you install 8.1.0, device will still be running 8.0.1 code which does not have the auto reload feature.</p></div><h2 id="can-the-reload-toast-message-be-suppressed" tabindex="-1">Can the reload toast message be suppressed? <a class="header-anchor" href="#can-the-reload-toast-message-be-suppressed" aria-label="Permalink to &quot;Can the reload toast message be suppressed?&quot;">​</a></h2><p>No, the toast messages exist to satisfy the requirement of Frontend UIX JavaScript code matching the UIX integration code.</p><p>The toast is shown when UIX has been changed and Home Assistant has restarted, but the browser is still running a cached UIX bundle from a different version.</p><p>An auto reload happens after 60 seconds, allowing unattended kiosks to update their Frontend code.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>After updating UIX, restart Home Assistant when you are ready to activate the update. Until then, UIX continues serving the version that was loaded when Home Assistant started.</p></div><h2 id="how-do-i-uninstall-ui-extension" tabindex="-1">How do I uninstall UI eXtension? <a class="header-anchor" href="#how-do-i-uninstall-ui-extension" aria-label="Permalink to &quot;How do I uninstall UI eXtension?&quot;">​</a></h2><p>Uninstallation of UI eXtension is a two step process. First, remove the service entry in Devices &amp; services. Next uninstall the integration either using HACS or manually removing the <code>uix</code> folder from <code>custom_components</code> directory if you installed manually.</p>',26)])])}const p=t(s,[["render",i]]);export{g as __pageData,p as default};
